  "content": "import unittest

import tenacity


class TestRetryIfNotExceptionType(unittest.TestCase):
    def test_retry_if_not_exception_type_retries_on_other_exceptions(self):
        class CustomError(Exception):
            pass

        call_count = [0]

        @tenacity.retry(
            stop=tenacity.stop_after_attempt(3),
            retry=tenacity.retry_if_not_exception_type(IOError),
        )
        def fails_with_custom():
            call_count[0] += 1
            raise CustomError()

        with self.assertRaises(tenacity.RetryError):
            fails_with_custom()
        self.assertEqual(call_count[0], 3)

    def test_retry_if_not_exception_type_does_not_retry_on_specified_exception(self):
        call_count = [0]

        @tenacity.retry(
            stop=tenacity.stop_after_attempt(3),
            retry=tenacity.retry_if_not_exception_type(IOError),
        )
        def fails_with_ioerror():
            call_count[0] += 1
            raise IOError("test")

        with self.assertRaises(IOError):
            fails_with_ioerror()
        self.assertEqual(call_count[0], 1)

